import{_ as t,c as o,o as d,ag as s}from"./chunks/framework._xRlcm3f.js";const r="/siyuan-plugin-publisher/images/shots/path-vuepress.webp",g=JSON.parse('{"title":"Vuepress 配置指南","description":"","frontmatter":{},"headers":[],"relativePath":"platforms/github-vuepress.md","filePath":"platforms/github-vuepress.md","lastUpdated":1790228279000}'),c={name:"platforms/github-vuepress.md"};function a(i,e,l,n,u,p){return d(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="vuepress-配置指南" tabindex="-1">Vuepress 配置指南 <a class="header-anchor" href="#vuepress-配置指南" aria-label="Permalink to &quot;Vuepress 配置指南&quot;">​</a></h1><p>通过 <strong>GitHub API</strong> 将文章发布到 <strong>Vuepress1</strong> 静态博客仓库。</p><h2 id="一、准备" tabindex="-1">一、准备 <a class="header-anchor" href="#一、准备" aria-label="Permalink to &quot;一、准备&quot;">​</a></h2><ol><li>一个可作为 Vuepress1 博客仓库的 <strong>GitHub 仓库</strong>（如 <code>terwer/terwer.github.io</code>）。</li><li>一个对该仓库有 <strong>push 权限</strong> 的 <strong>GitHub Token（PAT）</strong>（GitHub Settings → Developer settings → Personal access tokens，勾选 <code>repo</code> 权限）。</li><li>该仓库是一个标准 Vuepress1 项目，文章放在 <code>docs/</code> 目录，静态资源放在 <code>docs/.vuepress/public/</code>。</li></ol><h2 id="二、配置" tabindex="-1">二、配置 <a class="header-anchor" href="#二、配置" aria-label="Permalink to &quot;二、配置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>填什么</th></tr></thead><tbody><tr><td>首页地址</td><td>GitHub 首页地址，默认 <code>https://github.com</code></td></tr><tr><td>API 地址</td><td>GitHub API 地址，默认 <code>https://api.github.com</code>，通常无需修改</td></tr><tr><td>用户名</td><td>GitHub 用户名（owner），用于拼出仓库地址</td></tr><tr><td>鉴权 Token</td><td>GitHub 个人访问令牌（PAT），需对目标仓库有 push 权限</td></tr><tr><td>git 仓库名</td><td>Vuepress 博客仓库名，与用户名组成 <code>&lt;user&gt;/&lt;repo&gt;</code>，如 <code>terwer/terwer.github.io</code></td></tr><tr><td>默认分支</td><td>发布到的分支，默认 <code>main</code>，需与仓库实际分支一致</td></tr><tr><td>存储目录</td><td>Vuepress 文章存储目录，默认 <code>docs</code>。发布后的 <code>.md</code> 写入该目录</td></tr><tr><td>文件规则</td><td>文章文件名规则，默认 <code>[filename].md</code></td></tr><tr><td>文章预览规则</td><td>站点文章预览规则，默认 <code>/post/[postid].html</code></td></tr><tr><td>预览规则</td><td>GitHub blob 预览规则，默认 <code>/[user]/[repo]/blob/[branch]/[docpath]</code></td></tr><tr><td>图床</td><td>Vuepress 支持内置图床，选「当前平台」：图片上传到仓库 <code>docs/.vuepress/public/images</code>（默认），文章中引用为绝对路径 <code>/images/&lt;图片名&gt;</code></td></tr></tbody></table><h2 id="三、图片与目录约定-vuepress" tabindex="-1">三、图片与目录约定（Vuepress） <a class="header-anchor" href="#三、图片与目录约定-vuepress" aria-label="Permalink to &quot;三、图片与目录约定（Vuepress）&quot;">​</a></h2><ul><li>Vuepress1 的文章来源目录是 <strong><code>docs/</code></strong>，文章 <code>.md</code> 写入该目录，文件名默认 <code>[filename].md</code>。</li><li>图片选「当前平台」图床时，会提交到仓库根目录的 <strong><code>docs/.vuepress/public/images/</code></strong>，文章内引用为 <strong>绝对路径 <code>/images/&lt;图片名&gt;</code></strong>。</li><li>Vuepress 构建时把 <code>.vuepress/public</code> 目录映射到站点根，因此 <code>/images/...</code> 引用在构建产物中能正确显示。</li><li>文章 front matter 会写入的字段：<code>title</code>、<code>date</code>、<code>categories</code>、<code>article</code>（标题含 <code>[日记]</code> 时为 <code>false</code>），以及 <code>author</code>（<code>{ name, link }</code>，取自配置的「作者」与「作者主页」，主页留空时用「平台首页 + 用户名」拼出）。开启「YAML 永久链接」且文章有别名时再写入 <code>permalink</code>，取值<strong>固定为 <code>/post/&lt;文章别名&gt;.html</code></strong>（不读取「文章预览规则」）。「YAML 预设配置」留空则不额外补字段，填写时同名键会覆盖上述自动生成的值（含 <code>author</code>）。</li></ul><h2 id="四、验证与发布" tabindex="-1">四、验证与发布 <a class="header-anchor" href="#四、验证与发布" aria-label="Permalink to &quot;四、验证与发布&quot;">​</a></h2><ol><li>点「验证」→ Token、仓库、分支校验通过 → 保持「配置已保存并验证通过」。</li><li>快速发布 → 选 Vuepress → 发布。文章 <code>.md</code> 会提交到 <code>存储目录/[filename].md</code>。</li><li>点「查看文章」能打开仓库中该 <code>.md</code> 的 blob 地址；带图发布时图片会一并上传到仓库 <code>docs/.vuepress/public/images</code> 并在文章中引用 <code>/images/&lt;图片名&gt;</code>。</li></ol><h2 id="图片存储路径" tabindex="-1">图片存储路径 <a class="header-anchor" href="#图片存储路径" aria-label="Permalink to &quot;图片存储路径&quot;">​</a></h2><p>图床选「当前平台」时，可以指定图片存到仓库哪里：</p><p><img src="'+r+'" alt="填写图片存储目录与访问链接" loading="lazy"></p><table tabindex="0"><thead><tr><th>字段</th><th>默认值</th></tr></thead><tbody><tr><td>图片存储目录</td><td><code>docs/.vuepress/public/images</code></td></tr><tr><td>图片访问链接</td><td><code>images</code></td></tr></tbody></table><p>VuePress 的静态资源放在 <code>.vuepress/public</code> 下，构建后映射到站点根。一般不需要改，改了请保证两个值<strong>对应</strong>。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><ul><li><strong>验证通过但发布失败</strong>：确认 Token 对目标仓库有 push 权限，仓库名与分支正确，存储目录已存在。权限不足会收到 401/403。</li><li><strong>图片要怎么发布</strong>：选「当前平台」图床，图片上传到仓库 <code>docs/.vuepress/public/images</code>，文章中引用绝对路径 <code>/images/&lt;图片名&gt;</code>。构建时该目录映射到站点根，因此 <code>/images/...</code> 能正确显示。</li><li><strong>查看链接打不开</strong>：查看链接默认是仓库 blob 地址（<code>/[user]/[repo]/blob/[branch]/[docpath]</code>），仓库中存在该 <code>.md</code> 即可打开；若改为站点文章预览规则，需站点已部署且地址与规则一致。</li><li><strong>发布后线上没有新文章</strong>：Vuepress1 是通过构建（<code>npm run docs:build</code>）从 <code>docs/</code> 生成站点的，仅推送 <code>.md</code> 不会直接改变已部署站点；需配置自动构建（GitHub Actions / Pages / Vercel / Netlify 等）并触发一次构建。</li><li><strong>更新与删除</strong>：点「更新」会重新提交并产生一次新提交；「删除」会从仓库移除对应 <code>.md</code>，需重新构建才能从站点移除。</li></ul>',17)])])}const b=t(c,[["render",a]]);export{g as __pageData,b as default};
